// l10n.yaml (project root)
//   arb-dir: lib/l10n
//   template-arb-file: app_en.arb
//   output-localization-file: app_localizations.dart
//   nullable-getter: false
//
// lib/l10n/app_en.arb
//   { "@@locale": "en", "cartTitle": "Cart",
//     "@cartTitle": { "description": "Title of the shopping cart screen" } }
// lib/l10n/app_ru.arb
//   { "@@locale": "ru", "cartTitle": "Корзина" }

import 'package:flutter/material.dart';
import 'package:flutter_localizations/flutter_localizations.dart';
import 'l10n/app_localizations.dart'; // generated, committed or gitignored

class App extends StatelessWidget {
  const App({super.key});

  @override
  Widget build(BuildContext context) {
    // ❌ AppLocalizations.of(context) here is null — this context is ABOVE
    //    the Localizations widget MaterialApp is about to insert.
    return MaterialApp(
      localizationsDelegates: AppLocalizations.localizationsDelegates,
      supportedLocales: AppLocalizations.supportedLocales,
      home: const CartPage(),
    );
  }
}

class CartPage extends StatelessWidget {
  const CartPage({super.key});

  @override
  Widget build(BuildContext context) {
    // ✅ a descendant of MaterialApp — the delegate is above this context
    final l10n = AppLocalizations.of(context);
    return Scaffold(appBar: AppBar(title: Text(l10n.cartTitle)));
  }
}

