Widget removeChip(BuildContext context) {
  final scheme = Theme.of(context).colorScheme;
  return SizedBox(
    width: kMinInteractiveDimension,     // 48.0
    height: kMinInteractiveDimension,
    child: InkWell(
      onTap: _remove,
      customBorder: const CircleBorder(),
      child: Padding(                    // inside -> part of the hit test
        padding: const EdgeInsets.all(12),
        child: Icon(Icons.close, size: 24, color: scheme.onSurfaceVariant),
      ),
    ),
  );
}

