class Reveal extends StatelessWidget {
  const Reveal({super.key, required this.child, required this.animation});
  final Widget child;
  final Animation<double> animation;

  @override
  Widget build(BuildContext context) {
    // ❌ ignores the setting: slides on every device
    // return SlideTransition(position: _offset.animate(animation), child: child);

    // ✅ keep the state change, drop the travel
    if (MediaQuery.disableAnimationsOf(context)) {
      return FadeTransition(opacity: animation, child: child);
    }
    return SlideTransition(
      position: Tween(begin: const Offset(0, 0.15), end: Offset.zero).animate(animation),
      child: FadeTransition(opacity: animation, child: child),
    );
  }
}

