final localeStore = ValueNotifier<Locale?>(null);   // null = follow the system

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  final prefs = await SharedPreferences.getInstance();
  final saved = prefs.getString('locale');
  localeStore.value = saved == null ? null : Locale(saved);   // before the first frame
  runApp(const App());
}

class App extends StatelessWidget {
  const App({super.key});

  @override
  Widget build(BuildContext context) => ValueListenableBuilder<Locale?>(
        valueListenable: localeStore,
        builder: (context, locale, _) => MaterialApp(
          locale: locale,                                  // non-null pins the app
          supportedLocales: AppLocalizations.supportedLocales,
          localizationsDelegates: AppLocalizations.localizationsDelegates,
          localeListResolutionCallback: (preferred, supported) {
            // pt-BR content is fine for a pt-PT speaker; say so explicitly
            for (final l in preferred ?? const <Locale>[]) {
              if (l.languageCode == 'pt') return const Locale('pt', 'BR');
            }
            return null;                                   // null = default algorithm
          },
          home: const HomePage(),
        ),
      );
}

Future<void> setLanguage(String? code) async {
  final prefs = await SharedPreferences.getInstance();
  if (code == null) {
    await prefs.remove('locale');
  } else {
    await prefs.setString('locale', code);
  }
  Intl.defaultLocale = code;        // keeps intl formatting outside widgets in sync
  localeStore.value = code == null ? null : Locale(code);
}

