// ✅ the Bloc emits the failure; the widget translates it at paint time,
//    so a language switch rebuilds the message along with everything else
class PayError extends StatelessWidget {
  const PayError(this.failure, {super.key});
  final Failure failure;

  @override
  Widget build(BuildContext context) {
    final l10n = AppLocalizations.of(context)!;
    final locale = Localizations.localeOf(context).toString();
    final text = switch (failure) {          // sealed: a new subtype fails to compile here
      InsufficientFunds(:final shortfall) =>
        l10n.insufficientFunds(NumberFormat.currency(locale: locale).parse(shortfall)),
      SessionExpired() => l10n.sessionExpired,
      UnknownFailure(:final code) => l10n.genericErrorWithCode(code),
    };
    return Text(text);
  }
}

