class SparklinePainter extends CustomPainter {
  SparklinePainter(this.points, this.labels);
  final List<double> points;
  final List<String> labels;

  @override
  void paint(Canvas canvas, Size size) { /* draws pixels; the OS sees none of this */ }

  // One node per bar, so the reader can walk the series
  @override
  SemanticsBuilderCallback get semanticsBuilder => (Size size) {
        final w = size.width / points.length;
        return [
          for (var i = 0; i < points.length; i++)
            CustomPainterSemantics(
              rect: Rect.fromLTWH(i * w, 0, w, size.height),   // must be non-empty
              properties: SemanticsProperties(
                label: '${labels[i]}: ${points[i].round()}',
                textDirection: TextDirection.ltr,              // a label without one asserts
              ),
            ),
        ];
      };

  @override
  bool shouldRepaint(SparklinePainter old) => old.points != points;

  @override
  bool shouldRebuildSemantics(SparklinePainter old) =>       // NOT implied by shouldRepaint
      old.points != points || old.labels != labels;
}

