// A custom RenderObject describes itself instead
class RenderRating extends RenderBox {
  int _stars = 0;
  set stars(int value) {
    if (value == _stars) return;
    _stars = value;
    markNeedsPaint();
    markNeedsSemanticsUpdate();          // paint alone never refreshes the label
  }

  @override
  void describeSemanticsConfiguration(SemanticsConfiguration config) {
    super.describeSemanticsConfiguration(config);
    config
      ..isSemanticBoundary = true
      ..label = 'Rating'
      ..value = '$_stars of 5'
      ..textDirection = TextDirection.ltr
      ..onIncrease = () => stars = (_stars + 1).clamp(0, 5);
  }
}

// tool/pseudo_loc.dart — run in CI before `flutter gen-l10n` on debug builds.
// Turns app_en.arb into a locale that exposes overflow and hardcoded strings.
import 'dart:convert';
import 'dart:io';

const _accents = {
  'a': 'ä', 'e': 'ê', 'i': 'ï', 'o': 'ö', 'u': 'ü', 'y': 'ý',
  'A': 'Å', 'E': 'Ë', 'I': 'Ï', 'O': 'Ö', 'U': 'Ü', 'S': 'Š',
};

/// Accents the prose, pads by 40% and brackets the message, so a clipped or
/// concatenated string is obvious on screen. Placeholders stay untouched.
String pseudo(String source) {
  final out = StringBuffer('[');
  var inPlaceholder = false;
  for (final ch in source.split('')) {
    if (ch == '{') inPlaceholder = true;
    out.write(inPlaceholder ? ch : (_accents[ch] ?? ch));
    if (ch == '}') inPlaceholder = false;
  }
  return '$out${'·' * (source.length * 0.4).round()}]';
}

void main() {
  final src = jsonDecode(File('lib/l10n/app_en.arb').readAsStringSync())
      as Map<String, dynamic>;
  final out = <String, dynamic>{'@@locale': 'en_XA'};
  src.forEach((key, value) {
    if (key.startsWith('@')) return;              // metadata belongs to the source ARB
    final message = value as String;
    // ICU plural/select bodies are syntax, not prose — leave them alone
    out[key] = message.contains(', plural,') || message.contains(', select,')
        ? message
        : pseudo(message);
  });
  File('lib/l10n/app_en_XA.arb')
      .writeAsStringSync(const JsonEncoder.withIndent('  ').convert(out));
}

